Creating a complex smart contract involves a deep understanding of blockchain technology, programming languages like Solidity (for Ethereum-based contracts), and the specific requirements of the contract. Smart contracts are self-executing contracts with the terms of the agreement directly written into code. They automatically enforce and execute the terms of a contract when predefined conditions are met.

Here's a simplified example of a complex smart contract written in Solidity, which could be used for a decentralized voting system. This contract includes features like voter registration, candidate registration, voting, and result tallying. Please note that this is a basic example for educational purposes and not suitable for production without further development and security audits.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract DecentralizedVoting {
    struct Voter {
        bool isRegistered;
        bool hasVoted;
    }

    struct Candidate {
        string name;
        uint voteCount;
    }

    address public owner;
    mapping(address => Voter) public voters;
    Candidate[] public candidates;
    bool public votingEnded;

    modifier onlyOwner() {
        require(msg.sender == owner, "Only the owner can perform this action.");
        _;
    }

    modifier votingNotEnded() {
        require(!votingEnded, "Voting has already ended.");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function registerVoter(address voter) public onlyOwner {
        require(!voters[voter].isRegistered, "Voter is already registered.");
        voters[voter].isRegistered = true;
    }

    function registerCandidate(string memory name) public onlyOwner {
        candidates.push(Candidate(name, 0));
    }

    function vote(uint candidateIndex) public votingNotEnded {
        require(voters[msg.sender].isRegistered, "Voter is not registered.");
        require(!voters[msg.sender].hasVoted, "Voter has already voted.");
        require(candidateIndex < candidates.length, "Invalid candidate index.");

        voters[msg.sender].hasVoted = true;
        candidates[candidateIndex].voteCount += 1;
    }

    function endVoting() public onlyOwner {
        votingEnded = true;
    }

    function getWinner() public view returns (string memory winnerName, uint winnerVoteCount) {
        require(votingEnded, "Voting has not ended yet.");
        uint winningVoteCount = 0;

        for (uint i = 0; i < candidates.length; i++) {
            if (candidates[i].voteCount > winningVoteCount) {
                winningVoteCount = candidates[i].voteCount;
                winnerName = candidates[i].name;
            }
        }

        winnerVoteCount = winningVoteCount;
    }
}
```

This contract allows the owner to register voters and candidates, voters to vote for candidates, and the owner to end the voting process. After voting ends, anyone can call `getWinner` to find out the candidate with the most votes.

Remember, this is a basic example. Real-world smart contracts need to consider security, gas optimization, and more complex scenarios. Always have smart contracts reviewed and audited by professionals before deploying them on the mainnet.

